package probe

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"io"
	"math/rand/v2"
	"net"
	"net/http"
	"strconv"
	"strings"
	"time"

	"tropa.local/probe/internal/wire"
)

const registrationHost = "api.devices.cloudflare.com"

// Public bootstrap identity from WarpScout v0.16.1 warp.go (9e2ce957).
// It only carries enrollment requests; personal keys are generated by Rust.
var registrationIdentity = wire.WGIdentity{
	PrivateKey:    "4OnO86dDLpqJ2U10ODwX3tarx6xlRGLfkmbSBtMgaHg=",
	PeerPublicKey: "bmXOC+F1FxEMF9dyiK2H5/1SUtzH0JuVo51h2wPfgyo=",
	IPv4:          "172.16.0.2",
}

type registrationRequest struct {
	Method string          `json:"method"`
	Path   string          `json:"path"`
	Token  string          `json:"token,omitempty"`
	Body   json.RawMessage `json:"body"`
}

type registrationResponse struct {
	Status int    `json:"status"`
	Body   []byte `json:"body"`
}

func registrationVersion(r registrationRequest) (string, string, bool) {
	for _, version := range []struct{ path, client, agent string }{
		{"/v0a4005/reg", "a-6.11-2223", "okhttp/3.12.1"},
		{"/v0a4471/reg", "a-6.35-4471", "WARP for Android"},
	} {
		device, patch := strings.CutPrefix(r.Path, version.path+"/")
		if r.Method == "POST" && r.Path == version.path && r.Token == "" ||
			r.Method == "PATCH" && patch && device != "" && !strings.ContainsAny(device, "/?#%\\") && r.Token != "" {
			return version.client, version.agent, true
		}
	}
	return "", "", false
}

func registrationPipe(ctx context.Context, input io.Reader, output io.Writer, client *http.Client) error {
	for {
		data, err := wire.ReadFrame(input)
		if errors.Is(err, io.EOF) {
			return nil
		}
		if err != nil {
			return err
		}
		var message registrationRequest
		decoder := json.NewDecoder(bytes.NewReader(data))
		decoder.DisallowUnknownFields()
		if err := decoder.Decode(&message); err != nil {
			return errors.New("invalid enrollment frame")
		}
		version, agent, valid := registrationVersion(message)
		if !valid || !json.Valid(message.Body) || len(message.Body) > 16384 {
			return errors.New("invalid enrollment request")
		}
		request, err := http.NewRequestWithContext(ctx, message.Method, "https://"+registrationHost+message.Path, bytes.NewReader(message.Body))
		if err != nil {
			return errors.New("invalid enrollment request")
		}
		request.Header.Set("Content-Type", "application/json")
		request.Header.Set("CF-Client-Version", version)
		request.Header.Set("User-Agent", agent)
		if message.Token != "" {
			request.Header.Set("Authorization", "Bearer "+message.Token)
		}
		response, err := client.Do(request)
		if err != nil {
			return errors.New("enrollment request failed")
		}
		body, readErr := io.ReadAll(io.LimitReader(response.Body, 64*1024+1))
		response.Body.Close()
		if readErr != nil || len(body) > 64*1024 {
			return errors.New("invalid enrollment response")
		}
		encoded, err := json.Marshal(registrationResponse{Status: response.StatusCode, Body: body})
		if err != nil {
			return err
		}
		if err := wire.WriteFrame(output, encoded); err != nil {
			return err
		}
	}
}

func registrationTargets() []string {
	prefixes := []string{"8.6.112", "8.34.70", "8.34.146", "8.35.211", "8.39.125", "8.39.204", "8.39.214", "8.47.69", "162.159.192", "162.159.195", "188.114.96", "188.114.97", "188.114.98", "188.114.99"}
	rand.Shuffle(len(prefixes), func(i, j int) { prefixes[i], prefixes[j] = prefixes[j], prefixes[i] })
	var targets []string
	for range 5 {
		for _, prefix := range prefixes {
			host := prefix + "." + strconv.Itoa(1+rand.IntN(254))
			for _, port := range []string{"2408", "500", "1701", "4500"} {
				targets = append(targets, net.JoinHostPort(host, port))
			}
		}
	}
	return targets
}

func registrationClient(session *wgSession, target string) *http.Client {
	return &http.Client{
		Timeout:       15 * time.Second,
		CheckRedirect: func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse },
		Transport: &http.Transport{DisableKeepAlives: true, DialContext: func(ctx context.Context, _, _ string) (net.Conn, error) {
			return session.DialContext(ctx, "tcp4", target)
		}},
	}
}

func discoverRegistration(ctx context.Context) (*wgSession, *http.Client, error) {
	api := net.JoinHostPort(registrationHost, "443")
	profiles, _ := TuningProfiles()
	// A small representative set leaves time for WG even when AWG is blocked.
	names := []string{"awg-default", "awg-stun-small", "awg-dns-google-small", "awg-sip-apple-small", "awg-junk-wide", "wg-default"}
	targets := registrationTargets()
	for _, name := range names {
		if ctx.Err() != nil {
			break
		}
		for _, profile := range profiles {
			if profile.Name != name {
				continue
			}
			stage, cancel := context.WithTimeout(ctx, 12*time.Second)
			session := discoverRegistrationProfile(stage, ctx, profile, targets, api)
			cancel()
			if session != nil {
				return session, registrationClient(session, api), nil
			}
		}
	}
	return nil, nil, errors.New("no registration tunnel")
}

func discoverRegistrationProfile(ctx, lifetime context.Context, profile wire.ParameterSet, targets []string, api string) *wgSession {
	for _, target := range targets {
		if ctx.Err() != nil {
			return nil
		}
		request := wire.ProbeRequest{Transport: profile.Transport, Targets: []string{target}, Identity: wire.Identity{WireGuard: &registrationIdentity}, Parameters: profile.Parameters, TimeoutMS: 800, TunnelLimit: 1}
		session, err := newWG(lifetime, request, target)
		if err != nil {
			continue
		}
		attempt, stop := context.WithTimeout(ctx, 800*time.Millisecond)
		handshake := session.Handshake(attempt)
		stop()
		if handshake {
			client := registrationClient(session, api)
			check, finish := context.WithTimeout(ctx, 3*time.Second)
			req, _ := http.NewRequestWithContext(check, "GET", "https://"+registrationHost+"/", nil)
			response, err := client.Do(req)
			if response != nil {
				response.Body.Close()
			}
			finish()
			client.CloseIdleConnections()
			if err == nil {
				return session
			}
		}
		session.Close()
	}
	return nil
}

func ServeRegistration(parent context.Context, input io.ReadCloser, output io.Writer, buildID string) error {
	ctx, cancel := context.WithTimeout(parent, 180*time.Second)
	defer cancel()
	reader, writer := io.Pipe()
	defer reader.Close()
	go func() { _, _ = io.Copy(writer, input); cancel(); writer.Close() }()
	session, client, err := discoverRegistration(ctx)
	if err != nil {
		return err
	}
	defer session.Close()
	defer client.CloseIdleConnections()
	hello, _ := json.Marshal(struct {
		BuildID string `json:"buildId"`
	}{buildID})
	if err := wire.WriteFrame(output, hello); err != nil {
		return err
	}
	return registrationPipe(ctx, reader, output, client)
}
